import{_ as n,C as a,c as r,o as l,a3 as o,G as s}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Employment types","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/setup/employment-types.md","filePath":"master/human-resources/employees/setup/employment-types.md","lastUpdated":1791902625000}'),p={name:"master/human-resources/employees/setup/employment-types.md"};function i(m,e,y,d,c,h){const t=a("ImagePopup");return l(),r("div",null,[e[0]||(e[0]=o('<h1 id="employment-types" tabindex="-1">Employment types <a class="header-anchor" href="#employment-types" aria-label="Permalink to &quot;Employment types&quot;">​</a></h1><p>An employment type describes the kind of contract or arrangement a role has, such as Full-Time, Intern or Temporary. You keep one list of types and reuse it. This keeps wording the same across all your job positions.</p><blockquote><p><strong>In simple words:</strong> An employment type is a label for how someone is employed.</p></blockquote><p>Open <code>Employees → Configurations → Employment Types</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>None. The list already holds 11 types. Add more only when you need a label that is missing.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has no tabs. Columns are <strong>Employment Type</strong>, <strong>Code</strong> and <strong>Country</strong>. Drag the handle on a row to change the order. You can group by name, code, country and more.</p>',7)),s(t,{src:"/images1/employees/set_emptype_list.png",alt:"Employment Types list with Employment Type, Code and Country columns showing Full-Time, Intern and Permanent"}),e[1]||(e[1]=o('<p>The sample types are Employee, Statutory, Thesis, Apprenticeship, Student, Intern, Full-Time, Interim, Seasonal, Temporary and Permanent.</p><h2 id="create-an-employment-type" tabindex="-1">Create an employment type <a class="header-anchor" href="#create-an-employment-type" aria-label="Permalink to &quot;Create an employment type&quot;">​</a></h2><p>This example adds <strong>Contractor</strong>.</p><ol><li>Open <code>Employees → Configurations → Employment Types</code>.</li><li>Click <strong>New Employment Type</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Employment Type:</em></strong> Required. Type <code>Contractor</code>.</li><li><strong><em>Code:</em></strong> Optional. A short code, such as <code>CONTRACTOR</code>.</li><li><strong><em>Country:</em></strong> Optional. It is empty at first. Pick a country if the type applies to one country only.</li></ul>',5)),s(t,{src:"/images1/employees/set_emptype_form.png",alt:"Create Employment Types window filled with Contractor, code CONTRACTOR and no country"}),e[2]||(e[2]=o('<ol start="4"><li>Click <strong>Create</strong>. The type appears in the list.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Click <strong>Create &amp; create another</strong> to add several types in a row.</p></div><h2 id="edit-or-delete" tabindex="-1">Edit or delete <a class="header-anchor" href="#edit-or-delete" aria-label="Permalink to &quot;Edit or delete&quot;">​</a></h2><p>Click <strong>Edit</strong> on a row to change it. Click <strong>Delete</strong> to remove it.</p><h2 id="where-employment-types-are-used" tabindex="-1">Where employment types are used <a class="header-anchor" href="#where-employment-types-are-used" aria-label="Permalink to &quot;Where employment types are used&quot;">​</a></h2><ul><li>The <strong>Job Positions</strong> form has an <strong>Employment Type</strong> field. See <a href="./job-positions.html">Job positions</a>.</li><li>You can filter job positions by employment type.</li><li>On the employee list, you can group employees by <strong>Employment Type</strong>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./job-positions.html">Job positions</a></li><li><a href="./../employees/employee-list.html">Employee list</a></li><li><a href="./">Setup overview</a></li></ul>',8))])}const T=n(p,[["render",i]]);export{g as __pageData,T as default};
